// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address to, uint256 depositAmount, uint256 seed) public {
        vm.assume(to != address(0));
        vm.assume(to != address(c));
        vm.assume(depositAmount > 0);
        address depositor = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = to.balance;
        vm.prank(address(this));
        c.migrateTo(to);
        assertTrue(to.balance == balanceBefore + depositAmount);
    }
}
